import { FileSessionStore, z } from 'genkit/beta';
import { ai } from './ai.js';
import { createRefund } from './db.js';
import { lookupOrder } from './tools.js';

const store = new FileSessionStore('.genkit/sessions');

const issueRefund = ai.defineTool(
  {
    name: 'issueRefund',
    description: 'Refunds an amount to the customer for an order. Only call this after approveRefund returned approved.',
    inputSchema: z.object({ orderId: z.string(), amount: z.number() }),
    outputSchema: z.object({ refundId: z.string() }),
  },
  async ({ orderId, amount }) => {
    const refundId = createRefund(orderId, amount);
    ai.currentSession().addArtifacts([{ name: `receipt-${refundId}`, parts: [{ data: { refundId, orderId, amount } }] }]);
    return { refundId };
  },
);

const approveRefund = ai.defineInterrupt({
  name: 'approveRefund',
  description: 'Asks a human to approve a refund before it is issued.',
  inputSchema: z.object({ orderId: z.string(), amount: z.number(), reason: z.string() }),
  outputSchema: z.object({ approved: z.boolean(), note: z.string().optional() }),
});

/** Answers order status questions. */
export const orderAgent = ai.defineAgent({
  name: 'orderAgent',
  description: 'Answers questions about an order: its status, delivery date, tracking code and total.',
  system:
    'You are the Northwind Supplies order desk. Answer questions about orders using the lookupOrder tool. ' +
    'Quote the status, ETA and tracking code exactly as the tool returns them. If an order is not found, say so. ' +
    'When the customer does not name an order, use the order id from earlier in the conversation; ask for one only when the conversation has none.',
  tools: [lookupOrder],
  maxTurns: 4,
  store,
});

/** Handles refund requests and pauses for human approval before refunding. */
export const refundAgent = ai.defineAgent({
  name: 'refundAgent',
  description: 'Handles refund requests for an order. Refunds need human approval.',
  system:
    'Look up the order, then call approveRefund, then issueRefund only if approved. Never refund without approval. ' +
    'The refund amount is always the order total as lookupOrder returns it; never ask the customer for an amount.',
  tools: [lookupOrder, approveRefund, issueRefund],
  toolChoice: 'auto',
  maxTurns: 6,
  store,
});

// ---------------------------------------------------------------------------
// defineAgent - shortcut that combines definePrompt + definePromptAgent
// ---------------------------------------------------------------------------

/**
 * Configuration for `defineAgent`, which combines prompt definition and agent
 * registration into a single call.
 */
export interface AgentConfig<
  State = unknown,
  I extends z.ZodTypeAny = z.ZodTypeAny,
> extends PromptConfig<I> {
  /**
   * Optional Zod schema describing the shape of the custom session state.
   *
   * When provided:
   * - The `State` type is inferred from the schema (no explicit generic needed).
   * - The JSON Schema is included in action metadata (`metadata.agent.stateSchema`)
   *   so the Dev UI and other tooling can inspect / validate the state.
   * - Custom state is validated at load time (from a snapshot store or from the
   *   client-supplied `init.state`).
   */
  stateSchema?: z.ZodType<State>;
  store?: SessionStore<State>;
  clientTransform?: ClientTransform<State>;
  /**
   * Input values for the prompt's input variables. Lets the same prompt
   * definition power differently-customized agents (e.g. supplying a different
   * `role` or `tone`). Type-checked against the prompt's `input.schema`.
   */
  promptInput?: z.infer<I>;
}

/**
 * Defines and registers an agent by creating a prompt and wiring it into a
 * multi-turn agent in one step.
 *
 * This is a convenience shortcut for:
 * ```ts
 * definePrompt(registry, promptConfig);
 * definePromptAgent(registry, { promptName: promptConfig.name, ... });
 * ```
 */
export function defineAgent<
  State = unknown,
  I extends z.ZodTypeAny = z.ZodTypeAny,
>(registry: Registry, config: AgentConfig<State, I>): Agent<State> {
  // Extract agent-specific fields from the combined config; the rest is
  // forwarded to definePrompt.
  const { stateSchema, store, clientTransform, promptInput, ...promptConfig } =
    config;

  // Register the prompt.
  definePrompt(registry, promptConfig);

  // Wire it into a prompt agent.
  return definePromptAgent<State, I>(registry, {
    promptName: promptConfig.name,
    description: promptConfig.description,
    promptInput,
    stateSchema,
    store,
    clientTransform,
  });
}

### Agents

> **Beta feature:** Agents require importing from `genkit/beta` instead of `genkit`:
>
> ```ts
> import { genkit } from 'genkit/beta';
> ```

Agents are stateful, multi-turn conversations built on top of prompts and tools. `defineAgent` bundles a system prompt, tools, and (optionally) a session store into a single ergonomic chat API. A `chat` carries state across turns automatically, so you don't have to thread message history by hand:

```ts
import { genkit, z, FileSessionStore } from 'genkit/beta';
import { googleAI } from '@genkit-ai/google-genai';

const ai = genkit({ plugins: [googleAI()] });

const getWeather = ai.defineTool(
  {
    name: 'getWeather',
    description: 'Get the current weather for a given location.',
    inputSchema: z.object({ location: z.string() }),
    outputSchema: z.object({ weather: z.string() }),
  },
  async ({ location }) => ({ weather: `Sunny in ${location}` })
);

const weatherAgent = ai.defineAgent({
  name: 'weatherAgent',
  system: 'You are a helpful weather assistant. Use the getWeather tool.',
  tools: [getWeather],
  // Optional: persist each turn as a resumable snapshot.
  store: new FileSessionStore('./.snapshots'),
});

const chat = weatherAgent.chat();

// First turn (streaming).
const turn = chat.sendStream('What is the weather in London?');
for await (const chunk of turn.stream) {
  process.stdout.write(chunk.text ?? '');
}
await turn.response;

// Follow-up turn reuses the same chat - state is carried automatically.
const res = await chat.send('Now say that in French');
console.log(res.text);
```

Agents can be served over HTTP and accessed from the client with `remoteAgent`, which returns the exact same chat API as the server:

```ts
import { remoteAgent } from 'genkit/beta/client';

const AGENT_URL = 'YOUR_AGENT_URL';
const agent = remoteAgent({ url: AGENT_URL });
const chat = agent.chat();
const res = await chat.send('Weather in Tokyo?');
console.log(res.text);
```

Learn more in the [Agents documentation](https://genkit.dev/docs/js/agents/overview/).

## Middleware

The [`@genkit-ai/middleware`](https://www.npmjs.com/package/@genkit-ai/middleware) package provides ready-made middleware to add common functionality to your AI requests:

- **`retry`** - Automatically retry failed requests with exponential backoff.
- **`fallback`** - Fall back to alternative models on specific error statuses.
- **`toolApproval`** - Restrict tool execution to an approved list, interrupting unapproved calls for review.
- **`filesystem`** - Give the model sandboxed read/write access to a directory on the filesystem.
- **`skills`** - Scan for skill definitions and inject them as available tools.
- **`agents`** - Delegate to sub-agents by exposing each as a dedicated delegation tool.
- **`artifacts`** - Give the model tools to read, create, and update session artifacts.

```posix-terminal
npm install @genkit-ai/middleware
```

```ts
import { retry } from '@genkit-ai/middleware';

const { text } = await ai.generate({
  model: googleAI.model('gemini-flash-latest'),
  prompt: 'Why is Genkit awesome?',
  use: [
    retry({
      maxRetries: 3,
      initialDelayMs: 1000,
      backoffFactor: 2,
    }),
  ],
});
```

